sbe_mismatches.inferred:
∀ {α : Type u_1} {n : Nat} {β : Type u_2} {p : α → Prop} {xs : Vector { x // p x } n} {f : { x // p x } → Option β}
  {g : α → Option β},
  (∀ (x : α) (h : p x), f ⟨x, h⟩ = g x) → Array.findSome? f xs.toArray = Array.findSome? g xs.toArray.unattach

