goal:
∀ (x : Nat),
  Eq (Nat.bitwise or 0 x) =
    Eq
      (if 0 = 0 then if (false || true) = true then x else 0
      else
        if x = 0 then if (true || false) = true then 0 else 0
        else
          have n' := 0 / 2;
          have m' := x / 2;
          let b₁ := 0 % 2 = 1;
          let b₂ := x % 2 = 1;
          have r := Nat.bitwise or n' m';
          if (decide b₁ || decide b₂) = true
